import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/repositories/group_repository.dart';
import '../../widgets/app_drawer.dart';
import '../../widgets/summary_card.dart';

class DashboardScreen extends StatelessWidget { const DashboardScreen({super.key}); @override Widget build(BuildContext context){ final repo=context.read<GroupRepository>(); return Scaffold(appBar:AppBar(title:const Text('Mama Group Dashboard')),drawer:const AppDrawer(),body:RefreshIndicator(onRefresh:() async{},child:ListView(padding:const EdgeInsets.all(16),children:[StreamBuilder(stream:repo.members(),builder:(c,s)=>SummaryCard(title:'Total Members',value:'${s.data?.length??0}',icon:Icons.group)),FutureBuilder(future:repo.service.totals(),builder:(c,s){final t=s.data??{}; return Wrap(runSpacing:8,children:[SummaryCard(title:'Total Savings',value:'TZS ${t['savings']??0}',icon:Icons.savings),SummaryCard(title:'Total Loans',value:'TZS ${t['loans']??0}',icon:Icons.account_balance),SummaryCard(title:'Social Fund Balance',value:'TZS ${t['fund']??0}',icon:Icons.volunteer_activism)]);}),const SizedBox(height:16),const Text('Recent Transactions',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.savings(),builder:(c,s)=>Column(children:(s.data??[]).take(5).map((x)=>ListTile(leading:const Icon(Icons.payments),title:Text('Savings: TZS ${x.amount}'),subtitle:Text(x.date.toString()))).toList())),const Text('Upcoming Meetings',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.meetings(),builder:(c,s)=>Column(children:(s.data??[]).take(3).map((x)=>ListTile(leading:const Icon(Icons.event),title:Text(x.agenda),subtitle:Text(x.date.toString()))).toList()))])));}}
